# ================================================================================================
#   helpers
# ================================================================================================
def is_admin():
    if os.name != "nt":
        return True
    try:
        import ctypes
        return bool(ctypes.windll.shell32.IsUserAnAdmin())
    except Exception:
        return False


def relaunch_admin(page=None):
    """restart the suite elevated (UAC prompt).  True if the elevated copy was started."""
    if os.name != "nt":
        return False
    import ctypes
    exe = sys.executable
    if exe.lower().endswith("python.exe"):
        w = exe[:-10] + "pythonw.exe"
        exe = w if os.path.isfile(w) else exe
    args = [] if getattr(sys, "frozen", False) else [SUITE_FILE]
    if page:
        args += ["--page", page]
    cmd = " ".join('"%s"' % a for a in args)
    r = ctypes.windll.shell32.ShellExecuteW(None, "runas", exe, cmd, SUITE_DIR, 1)
    return r > 32


def pkg_state(mod):
    """(installed, version)"""
    try:
        ok = importlib.util.find_spec(mod) is not None
    except Exception:
        ok = False
    if not ok:
        return False, "-"
    try:
        from importlib import metadata
        names = {"docx": "python-docx", "PIL": "pillow"}
        return True, metadata.version(names.get(mod, mod))
    except Exception:
        return True, "?"


def _decode_source(key):
    return lzma.decompress(base64.b64decode("".join(_SRC[key].split()))).decode("utf-8")


def open_path(p):
    try:
        if os.name == "nt":
            os.startfile(p)
        elif sys.platform == "darwin":
            subprocess.Popen(["open", p])
        else:
            subprocess.Popen(["xdg-open", p])
    except Exception:
        pass



# ================================================================================================
#   reading / writing the input fields of a tool page (used by Projects)
# ================================================================================================
def _walk_fields(widget, path, out):
    kids = [c for c in widget.winfo_children() if c.winfo_class() != "Toplevel"]
    count = {}
    for c in kids:
        cls = c.winfo_class()
        i = count.get(cls, 0)
        count[cls] = i + 1
        p = "%s/%s%d" % (path, cls, i)
        if cls in FIELD_CLASSES:
            out[p] = c
        _walk_fields(c, p, out)


def capture_fields(root_widget):
    """{path: text} for every entry / dropdown / tick box / radio / slider of a tool window"""
    found = {}
    _walk_fields(root_widget, "", found)
    vals = {}
    for p, w in found.items():
        try:
            cls = w.winfo_class()
            opt = "variable" if cls in ("Checkbutton", "TCheckbutton", "Radiobutton", "TRadiobutton", "Scale", "TScale") \
                else "textvariable"
            var = str(w.cget(opt))
            if var:
                vals[p] = str(w.getvar(var))
            elif cls in ("Entry", "TEntry", "Spinbox", "TSpinbox") and str(w.cget("state")) == "normal":
                vals[p] = w.get()
            elif cls == "TCombobox":
                vals[p] = w.get()
        except Exception:
            pass
    return vals


def apply_fields(root_widget, values):
    found = {}
    _walk_fields(root_widget, "", found)
    n = 0
    for p, v in values.items():
        w = found.get(p)
        if w is None:
            continue
        try:
            cls = w.winfo_class()
            opt = "variable" if cls in ("Checkbutton", "TCheckbutton", "Radiobutton", "TRadiobutton", "Scale", "TScale") \
                else "textvariable"
            var = str(w.cget(opt))
            if var:
                w.setvar(var, v)
            elif cls == "TCombobox":
                w.set(v)
            elif str(w.cget("state")) == "normal":
                w.delete(0, "end")
                w.insert(0, v)
            else:
                continue
            n += 1
        except Exception:
            pass
    return n


def _safe_name(name):
    return re.sub(r"[^\w\- .]", "_", name).strip() or "project"


# ================================================================================================
#   embedding: a Frame that stands in for tk.Tk while a tool is being built
# ================================================================================================
class EmbeddedRoot(tk.Frame):
    """Tools are written as  class App(tk.Tk)  or  root = tk.Tk().  While a tool is built, tk.Tk is replaced
    by this Frame, so the tool's window becomes a page inside the suite.  Window-manager calls are ignored."""
    _master = None
    _hook = None
    last = None

    def __init__(self, *a, **k):
        tk.Frame.__init__(self, EmbeddedRoot._master)
        self._title = ""
        self._protocols = {}
        EmbeddedRoot.last = self

    # --- window manager calls a tool may make on its "root"
    def title(self, s=None):
        if s is not None:
            self._title = s
        return self._title
    wm_title = title

    def geometry(self, spec=None):
        if spec is None:
            return "%dx%d+%d+%d" % (self.winfo_width(), self.winfo_height(), self.winfo_rootx(), self.winfo_rooty())
        return None
    wm_geometry = geometry

    def minsize(self, *a):
        return None
    wm_minsize = minsize
    maxsize = wm_maxsize = resizable = wm_resizable = minsize

    def protocol(self, name=None, func=None):
        if func is not None:
            self._protocols[name] = func
        return ""
    wm_protocol = protocol

    def iconbitmap(self, *a, **k):
        return None
    iconphoto = wm_iconbitmap = wm_iconphoto = iconbitmap

    def attributes(self, *a, **k):
        return None
    wm_attributes = attributes

    def overrideredirect(self, *a):
        return None

    def state(self, *a):
        return "normal"
    wm_state = state

    def deiconify(self):
        return None
    iconify = withdraw = deiconify

    def mainloop(self, n=0):
        return None

    def destroy(self):
        hook = EmbeddedRoot._hook
        if hook is None or hook(self) is False:
            tk.Frame.destroy(self)
    quit = destroy


def _wm_transient(self, master=None):
    if isinstance(master, EmbeddedRoot):
        master = master.winfo_toplevel()
    return _RealWmTransient(self, master)


tk.Wm.wm_transient = _wm_transient
tk.Wm.transient = _wm_transient


@contextlib.contextmanager
def embedded_tk(master):
    """while active, tk.Tk (and TkinterDnD.Tk) create an EmbeddedRoot inside `master`"""
    EmbeddedRoot._master = master
    EmbeddedRoot.last = None
    saved = [(tk, "Tk", tk.Tk)]
    tk.Tk = EmbeddedRoot
    try:
        import tkinterdnd2
        saved.append((tkinterdnd2.TkinterDnD, "Tk", tkinterdnd2.TkinterDnD.Tk))
        tkinterdnd2.TkinterDnD.Tk = EmbeddedRoot
    except Exception:
        pass
    try:
        yield
    finally:
        for obj, name, val in saved:
            setattr(obj, name, val)


# ================================================================================================
#   scrolling page container
# ================================================================================================
class ScrollPage(tk.Frame):
    """Holds one page.  The page is at least as big as the window and gets scrollbars only when the
    tool needs more room than the window has."""

    def __init__(self, master, bg=PAGE_BG):
        tk.Frame.__init__(self, master, bg=bg)
        self.grid_rowconfigure(0, weight=1)
        self.grid_columnconfigure(0, weight=1)
        self.canvas = tk.Canvas(self, highlightthickness=0, bd=0, bg=bg)
        self.vbar = tk.Scrollbar(self, orient="vertical", command=self.canvas.yview)
        self.hbar = tk.Scrollbar(self, orient="horizontal", command=self.canvas.xview)
        self.canvas.configure(yscrollcommand=self.vbar.set, xscrollcommand=self.hbar.set)
        self.canvas.grid(row=0, column=0, sticky="nsew")
        self.inner = None
        self.win = None
        self.canvas.bind("<Configure>", self._fit)

    def attach(self, widget):
        self.inner = widget
        self.win = self.canvas.create_window(0, 0, window=widget, anchor="nw")
        widget.bind("<Configure>", self._fit, add="+")
        self._fit()

    def _fit(self, _e=None):
        if self.inner is None:
            return
        cw, ch = self.canvas.winfo_width(), self.canvas.winfo_height()
        rw, rh = self.inner.winfo_reqwidth(), self.inner.winfo_reqheight()
        w, h = max(cw, rw), max(ch, rh)
        self.canvas.itemconfigure(self.win, width=w, height=h)
        self.canvas.configure(scrollregion=(0, 0, w, h))
        if rh > ch + 2:
            self.vbar.grid(row=0, column=1, sticky="ns")
        else:
            self.vbar.grid_remove()
            self.canvas.yview_moveto(0)
        if rw > cw + 2:
            self.hbar.grid(row=1, column=0, sticky="ew")
        else:
            self.hbar.grid_remove()
            self.canvas.xview_moveto(0)

    def wheel(self, delta, shift=False):
        if shift and self.hbar.winfo_ismapped():
            self.canvas.xview_scroll(delta, "units")
        elif self.vbar.winfo_ismapped():
            self.canvas.yview_scroll(delta, "units")


# ================================================================================================
#   sidebar item
# ================================================================================================
class NavItem(tk.Frame):
    def __init__(self, master, text, sub, badge, command):
        tk.Frame.__init__(self, master, bg=SIDE_BG, cursor="hand2")
        self.command = command
        self.active = False
        self.bar = tk.Frame(self, width=4, bg=SIDE_BG)
        self.bar.pack(side="left", fill="y")
        self.badge = tk.Label(self, text=badge, width=2, bg="#EAEAEA", fg="#2A2A2A", font=(FONT, 9, "bold"))
        self.badge.pack(side="left", padx=(12, 10), pady=9)
        box = tk.Frame(self, bg=SIDE_BG)
        box.pack(side="left", fill="x", expand=True, pady=6)
        self.t1 = tk.Label(box, text=text, bg=SIDE_BG, fg=SIDE_TEXT, font=(FONT, 10, "bold"), anchor="w")
        self.t1.pack(fill="x")
        self.t2 = tk.Label(box, text=sub, bg=SIDE_BG, fg=SIDE_MUTED, font=(FONT, 8), anchor="w")
        self.t2.pack(fill="x")
        self._boxes = (self, box, self.t1, self.t2, self.badge)
        for w in (self, box, self.t1, self.t2, self.badge, self.bar):
            w.bind("<Button-1>", lambda e: self.command())
            w.bind("<Enter>", lambda e: self._paint(True))
            w.bind("<Leave>", lambda e: self._paint(False))

    def _paint(self, hover):
        bg = SIDE_ACTIVE if self.active else (SIDE_HOVER if hover else SIDE_BG)
        for w in (self, self._boxes[1], self.t1, self.t2):
            w.configure(bg=bg)
        self.badge.configure(bg=RED if self.active else "#EAEAEA", fg="#FFFFFF" if self.active else "#2A2A2A")
        self.t1.configure(fg=RED if self.active else SIDE_TEXT)
        self.t2.configure(fg="#777777")
        self.bar.configure(bg=RED if self.active else bg)

    def set_active(self, on):
        self.active = on
        self._paint(False)


# ================================================================================================
#   the suite window
# ================================================================================================
class Suite:
    def __init__(self, start_page=None):
        try:
            from tkinterdnd2 import TkinterDnD
            self.root = TkinterDnD.Tk()
        except Exception:
            self.root = _RealTk()
        self.root.title("%s  v%s" % (SUITE_NAME, SUITE_VERSION))
        sw, sh = self.root.winfo_screenwidth(), self.root.winfo_screenheight()
        w, h = min(1580, sw - 60), min(960, sh - 90)
        self.root.geometry("%dx%d+%d+%d" % (w, h, max(0, (sw - w) // 2), max(0, (sh - h) // 3)))
        self.root.minsize(min(1100, sw - 40), min(660, sh - 80))
        self.root.configure(bg=PAGE_BG)
        self.closing = False
        self.pages = {}          # key -> dict(page, root, theme, fonts)
        self.items = {}
        self.current = None
        self.exc_handlers = {}
        self._styles_ready = False
        self.proj = None                 # active project (dict) or None
        self.proj_path = None
        self.proj_dirty = False
        self.autosave = tk.BooleanVar(value=True)
        self.proj_var = tk.StringVar(value="(no project)")
        self.state = self._load_state()
        self.team_defaults = self._load_team_defaults()
        self.root.report_callback_exception = self._on_tk_error
        EmbeddedRoot._hook = self._embedded_destroy
        self._build_shell()
        self._build_home()
        self._build_help()
        self.root.bind_all("<MouseWheel>", self._wheel, add="+")
        self.root.bind_all("<Shift-MouseWheel>", lambda e: self._wheel(e, True), add="+")
        self.root.bind_all("<Button-4>", lambda e: self._wheel(e), add="+")
        self.root.bind_all("<Button-5>", lambda e: self._wheel(e), add="+")
        self.root.bind_all("<Control-Key-0>", lambda e: self.show("home"))
        for i, t in enumerate(TOOLS, 1):
            self.root.bind_all("<Control-Key-%d>" % i, lambda e, k=t["key"]: self.show(k))
        self.root.bind_all("<Control-Key-%d>" % (len(TOOLS) + 1), lambda e: self.show("help"))
        self.root.bind_all("<F1>", lambda e: self.show("help"))
        self.root.protocol("WM_DELETE_WINDOW", self.close)
        last = self.state.get("last_project")
        if last and os.path.isfile(last):
            self.open_project(last, quiet=True)
        self.refresh_projects_ui()
        self.show(start_page if start_page in TOOL_BY_KEY else "home")
        self.root.after(3000, self._tick)

    # ----------------------------------------------------------------- shell
    def _build_shell(self):
        r = self.root
        r.grid_columnconfigure(1, weight=1)
        r.grid_rowconfigure(0, weight=1)
        # sidebar
        side = tk.Frame(r, bg=SIDE_BG, width=262)
        side.grid(row=0, column=0, rowspan=2, sticky="ns")
        side.grid_propagate(False)
        side.pack_propagate(False)
        tk.Frame(side, bg=LINE, width=1).place(relx=1.0, rely=0, relheight=1.0, anchor="ne")
        logo = tk.Frame(side, bg="#FFFFFF")
        logo.pack(fill="x", pady=(0, 0))
        try:
            self._logo_img = None
            _lp = os.path.join(os.path.dirname(os.path.abspath(__file__)), "latrics_logo.png")
            if os.path.isfile(_lp):          # drop your full logo here (PNG) and it replaces the built-in one
                try:
                    from PIL import Image as _I, ImageTk as _IT
                    _im = _I.open(_lp).convert("RGBA")
                    _w = 232
                    _im = _im.resize((_w, max(1, int(_im.height * _w / _im.width))), _I.LANCZOS)
                    self._logo_img = _IT.PhotoImage(_im)
                except Exception:
                    self._logo_img = None
            if self._logo_img is None:
                self._logo_img = tk.PhotoImage(data=LOGO_B64)
            tk.Label(logo, image=self._logo_img, bg="#FFFFFF", bd=0).pack(padx=12, pady=10)
        except Exception:
            tk.Label(logo, text="LATRICS", bg="#FFFFFF", fg=RED, font=(FONT, 17, "bold")).pack(padx=18, pady=14)
        tk.Label(side, text="OPERATIONS SUITE", bg=SIDE_BG, fg=SIDE_MUTED, font=(FONT, 8, "bold")).pack(anchor="w", padx=18, pady=(10, 0))
        tk.Frame(side, bg=LINE, height=1).pack(fill="x", padx=18, pady=(10, 8))

        home = NavItem(side, "Dashboard", "Overview, packages, workflow", "H", lambda: self.show("home"))
        home.pack(fill="x")
        self.items["home"] = home
        group = None
        n = 0
        for t in TOOLS:
            n += 1
            if t["group"] != group:
                group = t["group"]
                tk.Label(side, text=group, bg=SIDE_BG, fg=SIDE_MUTED, font=(FONT, 8, "bold"),
                         anchor="w").pack(fill="x", padx=20, pady=(14, 2))
            it = NavItem(side, t["title"], t["short"], str(n), lambda k=t["key"]: self.show(k))
            it.pack(fill="x")
            self.items[t["key"]] = it
        tk.Label(side, text="HELP", bg=SIDE_BG, fg=SIDE_MUTED, font=(FONT, 8, "bold"),
                 anchor="w").pack(fill="x", padx=20, pady=(14, 2))
        hi = NavItem(side, "Help & Guide", "How every step works", "?", lambda: self.show("help"))
        hi.pack(fill="x")
        self.items["help"] = hi
        # footer
        foot = tk.Frame(side, bg=SIDE_BG)
        foot.pack(side="bottom", fill="x", padx=18, pady=14)
        adm = is_admin()
        chip = tk.Frame(foot, bg="#F2F2F2")
        chip.pack(fill="x")
        tk.Label(chip, text="●", bg="#F2F2F2", fg=(OK if adm else WARN), font=(FONT, 10)).pack(side="left", padx=(10, 4), pady=7)
        tk.Label(chip, text=("Administrator" if adm else "Standard user"), bg="#F2F2F2", fg=SIDE_TEXT,
                 font=(FONT, 9, "bold")).pack(side="left")
        if not adm and os.name == "nt":
            b = tk.Label(chip, text="Restart as admin", bg="#F2F2F2", fg=RED, font=(FONT, 8, "underline"),
                         cursor="hand2")
            b.pack(side="right", padx=10)
            b.bind("<Button-1>", lambda e: self._restart_admin())
        tk.Label(foot, text="v%s   Ctrl+0..%d switch tool" % (SUITE_VERSION, len(TOOLS) + 1), bg=SIDE_BG, fg=SIDE_MUTED,
                 font=(FONT, 8)).pack(anchor="w", pady=(8, 0))

        # header
        head = tk.Frame(r, bg=CARD_BG)
        head.grid(row=0, column=1, sticky="new")
        head.grid_columnconfigure(0, weight=1)
        hin = tk.Frame(head, bg=CARD_BG)
        hin.grid(row=0, column=0, sticky="ew", padx=22, pady=(12, 10))
        self.h_title = tk.Label(hin, text="", bg=CARD_BG, fg=CHAR, font=(FONT, 16, "bold"), anchor="w")
        self.h_title.pack(anchor="w")
        self.h_sub = tk.Label(hin, text="", bg=CARD_BG, fg=GREY, font=(FONT, 9), anchor="w", justify="left")
        self.h_sub.pack(anchor="w")
        self.h_proj = tk.Label(head, text="", bg="#F2F2F2", fg=CHAR, font=(FONT, 9, "bold"), padx=10, pady=3,
                               cursor="hand2")
        self.h_proj.grid(row=0, column=1, padx=(0, 8))
        self.h_proj.bind("<Button-1>", lambda e: self.show("home"))
        self.h_reset = tk.Label(head, text="Reset tool", bg="#F0F0F0", fg=CHAR, font=(FONT, 8, "bold"), padx=10,
                                pady=3, cursor="hand2")
        self.h_reset.grid(row=0, column=3, padx=(0, 8))
        self.h_reset.bind("<Button-1>", lambda e: self.reset_tool(self.current))
        self.h_default = tk.Label(head, text="Save as default", bg="#F0F0F0", fg=CHAR, font=(FONT, 8, "bold"), padx=10,
                                  pady=3, cursor="hand2")
        self.h_default.grid(row=0, column=2, padx=(0, 8))
        self.h_default.bind("<Button-1>", lambda e: self.save_team_default(self.current))
        self.h_chip = tk.Label(head, text="", bg=RED, fg="#FFFFFF", font=(FONT, 8, "bold"), padx=10, pady=3)
        self.h_chip.grid(row=0, column=4, padx=(0, 22))
        tk.Frame(head, bg=RED, height=3).grid(row=1, column=0, columnspan=5, sticky="ew")

        # content + status bar (header is row 0 -> content row 1 ... use a wrapper)
        r.grid_rowconfigure(0, weight=0)
        r.grid_rowconfigure(1, weight=1)
        r.grid_rowconfigure(2, weight=0)
        side.grid_configure(rowspan=3)
        self.content = tk.Frame(r, bg=PAGE_BG)
        self.content.grid(row=1, column=1, sticky="nsew")
        self.content.grid_rowconfigure(0, weight=1)
        self.content.grid_columnconfigure(0, weight=1)
        sb = tk.Frame(r, bg="#F0F0F0")
        # bottom bar removed
        self.status = tk.Label(sb, text="Ready", bg="#F0F0F0", fg=CHAR, font=(FONT, 9), anchor="w")
        self.status.pack(side="left", padx=14, pady=3)
        tk.Label(sb, text="Settings folder: " + SUITE_DIR, bg="#F0F0F0", fg=GREY, font=(FONT, 8)).pack(side="right", padx=14)

    # ----------------------------------------------------------------- navigation
    def show(self, key):
        if key not in ("home", "help") and key not in self.pages:
            self._open_tool(key)
        elif key == "home":
            self.pages.setdefault("home", self._home_entry)
        ent = self.pages.get(key)
        if ent is None:
            return
        self._autosave_now()
        self.current = key
        if key in ("home", "help"):
            self.h_reset.grid_remove()
            self.h_default.grid_remove()
        else:
            self.h_reset.grid()
            self.h_default.grid()
            if self.proj is not None:
                self.proj["tools"].setdefault(key, {})["last_used"] = time.strftime("%Y-%m-%d %H:%M")
                self.proj_dirty = True
                self._autosave_now()
        for k, it in self.items.items():
            it.set_active(k == key)
        if key == "home":
            self.h_title.config(text="Dashboard")
            self.h_sub.config(text="Welcome - pick a tool in the left sidebar, or use the cards below.")
            self.h_chip.config(text="OVERVIEW")
            self.home_page.tkraise()
            self.status.config(text="Ready")
            self.refresh_packages()
            self.refresh_projects_ui()
            return
        if key == "help":
            self.h_title.config(text="Help & Guide")
            self.h_sub.config(text="New here? Start with the quick start, then open the section of the tool you need.")
            self.h_chip.config(text="HELP")
            self.help_page.tkraise()
            self.status.config(text="Help & Guide  (F1)")
            self.refresh_help_defaults()
            return
        t = TOOL_BY_KEY[key]
        self.h_title.config(text=t["title"])
        self.h_sub.config(text="")
        self.h_chip.config(text=t["group"])
        ent["page"].tkraise()
        self._apply_look(ent)
        self.status.config(text="%s  -  %s" % (t["title"], t["io"]))

    _home_entry = {"page": None}

    def _embedded_destroy(self, inst):
        """a tool closed its window (Exit button) -> go back to the dashboard instead of destroying the page"""
        if self.closing:
            return False
        self.root.after(10, lambda: self.show("home"))
        return True

    def _on_tk_error(self, exc, val, tb):
        h = self.exc_handlers.get(self.current)
        if h:
            try:
                h(exc, val, tb)
                return
            except Exception:
                pass
        traceback.print_exception(exc, val, tb)
        try:
            messagebox.showerror(SUITE_NAME, "%s: %s" % (exc.__name__, val))
        except Exception:
            pass

    def _wheel(self, e, shift=False):
        if self.current == "help":
            sp = self.help_page
        else:
            ent = self.pages.get(self.current) if self.current != "home" else None
            sp = ent["page"] if ent else getattr(self, "home_page", None)
        if sp is None:
            return
        try:
            cls = e.widget.winfo_class()
        except Exception:
            return
        if cls in ("Text", "Treeview", "Listbox", "TCombobox", "Spinbox", "TSpinbox", "Scale", "TScale",
                   "Scrollbar", "TScrollbar", "Canvas", "Toplevel", "Menu"):
            if not (cls == "Canvas" and e.widget is sp.canvas):
                return
        if getattr(e, "num", 0) == 4:
            d = -3
        elif getattr(e, "num", 0) == 5:
            d = 3
        else:
            d = -3 if e.delta > 0 else 3
        sp.wheel(d, shift)

    # ----------------------------------------------------------------- look (ttk theme / fonts are global in Tk)
    FONT_NAMES = ("TkDefaultFont", "TkTextFont", "TkFixedFont", "TkMenuFont", "TkHeadingFont")

    def _snap(self):
        import tkinter.font as tkfont
        from tkinter import ttk
        fonts = {}
        for n in self.FONT_NAMES:
            try:
                fonts[n] = dict(tkfont.nametofont(n).actual())
            except Exception:
                pass
        return ttk.Style(self.root).theme_use(), fonts

    def _restore(self, theme, fonts):
        import tkinter.font as tkfont
        from tkinter import ttk
        try:
            ttk.Style(self.root).theme_use(theme)
        except Exception:
            pass
        for n, cfg in fonts.items():
            try:
                tkfont.nametofont(n).configure(**cfg)
            except Exception:
                pass

    def _apply_look(self, ent):
        if ent.get("theme") is not None:
            self._restore(ent["theme"], ent["fonts"])
        else:
            self._restore(*self.base_look)

    # ----------------------------------------------------------------- tools
    def _prepare(self, key):
        """things a tool expects on disk / in sys.modules"""
        if key == "ortho":
            name = "metashape_pipeline"
            src = _decode_source("metashape_pipeline")
            path = os.path.join(SUITE_DIR, name + ".py")
            try:
                old = open(path, encoding="utf-8").read() if os.path.isfile(path) else None
                if old != src:
                    with open(path, "w", encoding="utf-8", newline="\n") as f:
                        f.write(src)
            except Exception as ex:
                self.status.config(text="Could not write %s: %s" % (path, ex))
            mod = types.ModuleType(name)
            mod.__file__ = path
            sys.modules[name] = mod
            linecache.cache[path] = (len(src), None, src.splitlines(True), path)
            exec(compile(src, path, "exec"), mod.__dict__)

    def _load_module(self, t):
        name = "latrics_" + t["key"]
        path = os.path.join(SUITE_DIR, t["file"])
        src = _decode_source(t["key"])
        mod = types.ModuleType(name)
        mod.__file__ = path
        sys.modules[name] = mod
        linecache.cache[path] = (len(src), None, src.splitlines(True), path)
        exec(compile(src, path, "exec"), mod.__dict__)
        return mod

    def _open_tool(self, key):
        t = TOOL_BY_KEY[key]
        self.status.config(text="Loading %s ..." % t["title"])
        self.root.update_idletasks()
        page = ScrollPage(self.content)
        page.grid(row=0, column=0, sticky="nsew")
        ent = {"page": page}
        self.base_look = getattr(self, "base_look", None) or self._snap()
        before = self._snap()
        try:
            self._prepare(key)
            with embedded_tk(page.canvas):
                mod = self._load_module(t)
                if key == "lidar":
                    self._patch_lidar(mod)
                obj = getattr(mod, t["entry"])
                made = obj() if t["kind"] == "class" else obj()
                inst = made if isinstance(made, EmbeddedRoot) else EmbeddedRoot.last
            if inst is None:
                raise RuntimeError("the tool did not create a window")
            page.attach(inst)
            ent["inst"] = inst
            ent["defaults"] = capture_fields(inst)
            h = getattr(inst, "report_callback_exception", None)
            if h is not None and getattr(h, "__self__", None) is not inst:
                self.exc_handlers[key] = h
            after = self._snap()
            if after != before:
                ent["theme"], ent["fonts"] = after
                self._restore(*before)
            self.pages[key] = ent
            self._apply_project_to(key)
            self.root.after(400, lambda k=key: self._apply_project_to(k))
            self.status.config(text="%s ready" % t["title"])
        except BaseException as ex:                      # noqa  (SystemExit from a tool too)
            self._restore(*before)
            page.destroy()
            self._error_page(key, ex, traceback.format_exc())

    def _patch_lidar(self, mod):
        """the LiDAR tool restarts itself as Administrator with its own file name - restart the suite instead"""
        def relaunch_as_admin():
            ok = relaunch_admin("lidar")
            if ok:
                self.root.after(300, self.close_now)
            return ok
        mod.relaunch_as_admin = relaunch_as_admin

    def _error_page(self, key, ex, tb):
        t = TOOL_BY_KEY[key]
        page = ScrollPage(self.content)
        page.grid(row=0, column=0, sticky="nsew")
        box = tk.Frame(page.canvas, bg=PAGE_BG)
        card = tk.Frame(box, bg=CARD_BG, highlightbackground=LINE, highlightthickness=1)
        card.pack(padx=30, pady=30, anchor="nw")
        tk.Label(card, text="%s could not be opened" % t["title"], bg=CARD_BG, fg=RED, font=(FONT, 14, "bold")).pack(
            anchor="w", padx=20, pady=(16, 4))
        tk.Label(card, text=str(ex) or ex.__class__.__name__, bg=CARD_BG, fg=CHAR, font=(FONT, 10), wraplength=820,
                 justify="left").pack(anchor="w", padx=20)
        mod = getattr(ex, "name", None) if isinstance(ex, ImportError) else None
        row = tk.Frame(card, bg=CARD_BG)
        row.pack(anchor="w", padx=20, pady=12)
        if mod:
            pipname = next((p for m, p, _u, _r in PACKAGES if m == mod), mod)
            self._button(row, "Install  %s" % pipname, lambda: self._install([pipname], then=lambda: self._retry(key))).pack(
                side="left", padx=(0, 8))
        self._button(row, "Try again", lambda: self._retry(key), primary=False).pack(side="left")
        txt = tk.Text(card, height=14, width=110, font=("Consolas" if os.name == "nt" else "DejaVu Sans Mono", 8),
                      bg="#FAFAFA", relief="flat", highlightbackground=LINE, highlightthickness=1)
        txt.pack(padx=20, pady=(0, 18))
        txt.insert("1.0", tb)
        txt.configure(state="disabled")
        page.attach(box)
        self.pages[key] = {"page": page, "error": True}
        self.status.config(text="%s failed to open" % t["title"])

    def _retry(self, key):
        ent = self.pages.pop(key, None)
        if ent:
            ent["page"].destroy()
        self.show(key)

    # ----------------------------------------------------------------- dashboard
    def _button(self, parent, text, cmd, primary=True):
        bg, fg, hv = (RED, "#FFFFFF", RED_DARK) if primary else ("#F0F0F0", CHAR, "#E2E2E2")
        b = tk.Label(parent, text=text, bg=bg, fg=fg, font=(FONT, 9, "bold"), padx=16, pady=7, cursor="hand2")
        b.bind("<Button-1>", lambda e: cmd())
        b.bind("<Enter>", lambda e: b.configure(bg=hv))
        b.bind("<Leave>", lambda e: b.configure(bg=bg))
        return b

    def _build_home(self):
        self.home_page = ScrollPage(self.content)
        self.home_page.grid(row=0, column=0, sticky="nsew")
        body = tk.Frame(self.home_page.canvas, bg=PAGE_BG)
        body.grid_columnconfigure(0, weight=1)
        self._build_project_panel(body)
        # --- workflow strip
