    def refresh_packages(self):
        for w in self.pkg_frame.winfo_children():
            w.destroy()
        self.missing = []
        for c, h in enumerate(("Package", "Status", "Version", "Used by")):
            tk.Label(self.pkg_frame, text=h, bg=CARD_BG, fg=GREY, font=(FONT, 8, "bold"), anchor="w").grid(
                row=0, column=c, sticky="w", padx=(0, 22))
        for r, (mod, pip, used, req) in enumerate(PACKAGES, 1):
            ok, ver = pkg_state(mod)
            if not ok and req:
                self.missing.append(pip)
            txt, col = ("Installed", OK) if ok else (("MISSING", RED) if req else ("not installed", WARN))
            vals = ((pip, CHAR), (txt, col), (ver, CHAR), (used, GREY))
            for c, (v, fg) in enumerate(vals):
                tk.Label(self.pkg_frame, text=v, bg=CARD_BG, fg=fg, anchor="w",
                         font=(FONT, 9, "bold" if c == 1 else "normal")).grid(row=r, column=c, sticky="w", padx=(0, 22))

    def _install_missing(self):
        if not self.missing:
            messagebox.showinfo(SUITE_NAME, "All required packages are installed.")
            return
        self._install(self.missing)

    def _install(self, pkgs, then=None):
        win = tk.Toplevel(self.root)
        win.title("Installing " + ", ".join(pkgs))
        win.geometry("760x380")
        win.transient(self.root)
        txt = tk.Text(win, font=("Consolas" if os.name == "nt" else "DejaVu Sans Mono", 9), bg="#FAFAFA")
        txt.pack(fill="both", expand=True)
        txt.insert("end", "pip install %s\n\n" % " ".join(pkgs))

        def work():
            cmd = [sys.executable, "-m", "pip", "install", "--disable-pip-version-check"] + list(pkgs)
            try:
                p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                                     creationflags=0x08000000 if os.name == "nt" else 0)
                for line in iter(p.stdout.readline, b""):
                    self.root.after(0, lambda s=line.decode(errors="ignore"): (txt.insert("end", s), txt.see("end")))
                rc = p.wait()
            except Exception as ex:
                rc = -1
                self.root.after(0, lambda: txt.insert("end", "\n%s\n" % ex))
            import importlib
            importlib.invalidate_caches()

            def done():
                txt.insert("end", "\nFinished OK.\n" if rc == 0 else "\nFinished with errors (exit %s).\n" % rc)
                txt.see("end")
                self.refresh_packages()
                if rc == 0 and then:
                    win.destroy()
                    then()
            self.root.after(0, done)
        threading.Thread(target=work, daemon=True).start()

    def _restart_admin(self):
        if messagebox.askyesno(SUITE_NAME, "Restart the suite as Administrator?\n(Windows will ask for permission. "
                                           "Needed by the LiDAR Tool for PointsCreator.)"):
            if relaunch_admin(self.current if self.current in TOOL_BY_KEY else None):
                self.root.after(300, self.close_now)



    # ----------------------------------------------------------------- team defaults
    def _load_team_defaults(self):
        try:
            with open(DEFAULTS_FILE, encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {}

    def _save_team_defaults(self):
        try:
            with open(DEFAULTS_FILE, "w", encoding="utf-8") as f:
                json.dump(self.team_defaults, f, indent=2, ensure_ascii=False)
        except Exception as ex:
            self.status.config(text="Could not save defaults: %s" % ex)

    def _effective_defaults(self, key):
        """the tool's own defaults, overlaid with your saved team default for that tool"""
        base = dict(self.pages.get(key, {}).get("defaults", {}))
        base.update(self.team_defaults.get(key, {}))
        return base

    _full_defaults = _effective_defaults

    def save_team_default(self, key):
        ent = self.pages.get(key)
        if not ent or ent.get("inst") is None:
            return
        cap = capture_fields(ent["inst"])
        keep = {p: v for p, v in cap.items() if not (v and os.path.isdir(v))}      # project folders are not defaults
        if not messagebox.askyesno(
                SUITE_NAME, "Use the current settings of %s as the default for every NEW project?\n\n"
                            "Folder fields (your data folders) are not included. Existing projects keep their own "
                            "values." % TOOL_BY_KEY[key]["title"]):
            return
        self.team_defaults[key] = keep
        self._save_team_defaults()
        self.status.config(text="Saved as default: %s (%d fields)" % (TOOL_BY_KEY[key]["title"], len(keep)))
        self.refresh_help_defaults()

    def clear_team_default(self, key):
        if key in self.team_defaults:
            del self.team_defaults[key]
            self._save_team_defaults()
        self.refresh_help_defaults()
        self.status.config(text="Default cleared: %s" % TOOL_BY_KEY[key]["title"])

    def refresh_help_defaults(self):
        for w in self.help_def_frame.winfo_children():
            w.destroy()
        for r, t in enumerate(TOOLS):
            n = len(self.team_defaults.get(t["key"], {}))
            tk.Label(self.help_def_frame, text=t["title"], bg=CARD_BG, fg=CHAR, font=(FONT, 9, "bold"), width=20,
                     anchor="w").grid(row=r, column=0, sticky="w", pady=2)
            tk.Label(self.help_def_frame, text=("%d fields saved as default" % n) if n else "tool's own defaults",
                     bg=CARD_BG, fg=OK if n else GREY, font=(FONT, 9), width=26, anchor="w").grid(row=r, column=1)
            if n:
                self._button(self.help_def_frame, "Clear", lambda k=t["key"]: self.clear_team_default(k),
                             primary=False).grid(row=r, column=2, padx=6, pady=2)

